def parse_records(text):
    lines = text.splitlines()
    out = []
    for l in lines:
        if l.lstrip().startswith('#'):
            continue  # full-line comment: drop entirely
        # strip inline comment but preserve the (possibly now-blank) line
        if '#' in l:
            l = l.split('#', 1)[0]
        out.append(l.strip())
    return out

